func loadCallers(ctx context.Context, db *sql.DB, calleeName, targetModule string, onlyResolved bool, limit int) ([]callerInfo, int, error) {
	where := []string{"c.normalized_callee = ?"}
	args := []any{strings.ToLower(calleeName)}
	if onlyResolved {
		where = append(where, "c.resolved_proc_id IS NOT NULL")
	}
	if targetModule != "" {
		where = append(where, "rp.module_full_name = ?")
		args = append(args, targetModule)
	}
	whereSQL := strings.Join(where, " AND ")

	var total int
	countSQL := `
		SELECT COUNT(*)
		FROM calls c
		JOIN procedures caller ON caller.id = c.caller_proc_id
		LEFT JOIN procedures rp ON rp.id = c.resolved_proc_id
		WHERE ` + whereSQL
	if err := db.QueryRowContext(ctx, countSQL, args...).Scan(&total); err != nil {
		return nil, 0, fmt.Errorf("count callers: %w", err)
	}

	queryArgs := append([]any{}, args...)
	queryArgs = append(queryArgs, limit)
	rows, err := db.QueryContext(ctx, `
		SELECT c.line, c.call_text,
			caller.id, caller.module_full_name, caller.name, caller.start_line, caller.end_line,
			rp.id, rp.module_full_name, rp.name, rp.start_line, rp.end_line
		FROM calls c
		JOIN procedures caller ON caller.id = c.caller_proc_id
		LEFT JOIN procedures rp ON rp.id = c.resolved_proc_id
		WHERE `+whereSQL+`
		ORDER BY caller.module_full_name, caller.start_line, c.line
		LIMIT ?
	`, queryArgs...)
	if err != nil {
		return nil, 0, fmt.Errorf("query callers: %w", err)
	}
	defer rows.Close()

	var result []callerInfo
	for rows.Next() {
		var caller callerInfo
		if err := rows.Scan(
			&caller.Line,
			&caller.CallText,
			&caller.CallerID,
			&caller.CallerModule,
			&caller.CallerName,
			&caller.CallerStart,
			&caller.CallerEnd,
			&caller.TargetID,
			&caller.TargetModule,
			&caller.TargetName,
			&caller.TargetStart,
			&caller.TargetEnd,
		); err != nil {
			return nil, 0, fmt.Errorf("scan caller: %w", err)
		}
		result = append(result, caller)
	}
	if err := rows.Err(); err != nil {
		return nil, 0, fmt.Errorf("iterate callers: %w", err)
	}
	return result, total, nil
}

func collectTraceCallChains(summary *apiInvestigationSummaryResponse, from apiProcedure, call apiTraceCall, reason string, addProcedure func(module, name, reason string)) {
	edge := apiEvidenceTraceEdge{
		FromModule: from.Module,
		FromName:   from.Name,
		Line:       call.Line,
		CallText:   call.CallText,
		To:         call.Target,
	}
	addCallChain(summary, edge, reason)
	addProcedure(call.Target.Module, call.Target.Name, reason)
	for _, child := range call.Children {
		collectTraceCallChains(summary, call.Target, child, reason, addProcedure)
	}
}

func countTraceCalls(calls []apiTraceCall) int {
	total := 0
	for _, call := range calls {
		total++
		total += countTraceCalls(call.Children)
	}
	return total
}

func collectTraceModules(call apiTraceCall, modules map[string]bool) {
	modules[call.Target.Module] = true
	for _, child := range call.Children {
		collectTraceModules(child, modules)
	}
}

func sortedStringSet(values map[string]bool) []string {
	result := make([]string, 0, len(values))
	for value := range values {
		result = append(result, value)
	}
	for i := 1; i < len(result); i++ {
		for j := i; j > 0 && result[j] < result[j-1]; j-- {
			result[j], result[j-1] = result[j-1], result[j]
		}
	}
	return result
}
